import { createDeliveryScenePreview, createFormScenePreview, createMotionScenePreview, createStoreScenePreview } from "./studio-visual-scenes";

type StudioPreviewFile = { filePath: string; content: string; language: string };
type StudioPreview = { project: { name: string; projectType: string; framework: string }; files: StudioPreviewFile[] };

function escapeHtml(value: string) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\"/g, "&quot;").replace(/'/g, "&#039;");
}

function isCheckersProject(preview: StudioPreview) {
  return /\b(damas|checkers)\b/i.test(`${preview.project.name} ${preview.project.framework} ${preview.files.map((file) => file.content.slice(0, 300)).join(" ")}`);
}

type CheckersTheme = { label: string; title: string; start: string; end: string; opponentLabel: string; opponentTitle: string; opponentStart: string; opponentEnd: string; boardLight: string; boardDark: string; medieval: boolean; competitive: boolean };

function detectCheckersTheme(preview: StudioPreview): CheckersTheme {
  const configFile = preview.files.find((file) => file.filePath === "studio-preview.json")?.content;
  let configuredColor = "";
  let configuredTheme = "";
  let configuredOpponentColor = "";
  let configuredBoard = "";
  let configuredMode = "";
  try { const config = JSON.parse(configFile ?? "{}") as { checkers?: { pieceColor?: string; opponentColor?: string; board?: string; theme?: string; mode?: string } }; configuredColor = String(config.checkers?.pieceColor ?? "").toLowerCase(); configuredOpponentColor = String(config.checkers?.opponentColor ?? "").toLowerCase(); configuredBoard = String(config.checkers?.board ?? "").toLowerCase(); configuredTheme = String(config.checkers?.theme ?? "").toLowerCase(); configuredMode = String(config.checkers?.mode ?? "").toLowerCase(); } catch { configuredColor = ""; }
  const source = preview.files.map((file) => file.content).join("\n").toLowerCase();
  const medieval = configuredTheme === "medieval" || /medieval|reino|castelo/.test(source);
  const competitive = configuredMode === "competitive" || /ranqueamento|\belo\b|matchmaking|torneio|espectador|replay/.test(source);
  const palette = (color: string, fallback: [string, string, string, string]) => color === "pink" ? ["rosas", "Rosas", "#f9a8d4", "#be185d"] : color === "yellow" ? ["amarelas", "Amarelas", "#fde047", "#ca8a04"] : color === "red" ? ["vermelhas", "Vermelhas", "#fb7185", "#b91c1c"] : color === "green" ? ["verdes", "Verdes", "#4ade80", "#15803d"] : color === "blue" ? ["azuis", "Azuis", "#38bdf8", "#1d4ed8"] : fallback;
  const board = configuredBoard === "marble" ? ["#e5e7eb", "#374151"] : configuredBoard === "wood" ? ["#d6a56a", "#5b2e14"] : configuredBoard === "obsidian" ? ["#71717a", "#18181b"] : medieval ? ["#d8bb80", "#623617"] : ["#e7d7be", "#7c4b35"];
  const theme = (color: string, fallback: [string, string, string, string]): CheckersTheme => { const [label, title, start, end] = palette(color, fallback); const [opponentLabel, opponentTitle, opponentStart, opponentEnd] = palette(configuredOpponentColor, ["roxas", "Roxas", "#c084fc", "#6d28d9"]); return { label, title, start, end, opponentLabel, opponentTitle, opponentStart, opponentEnd, boardLight: board[0], boardDark: board[1], medieval, competitive }; };
  if (configuredColor) return theme(configuredColor, ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
  if (/rosa|pink|#f9a8d4|#be185d/.test(source)) return theme("pink", ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
  if (/amarel|#ffd60a|#facc15|#eab308/.test(source)) return theme("yellow", ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
  if (/vermelh|#ef4444|#dc2626|#f43f5e/.test(source)) return theme("red", ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
  if (/verde|#22c55e|#16a34a/.test(source)) return theme("green", ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
  return theme("blue", ["azuis", "Azuis", "#38bdf8", "#1d4ed8"]);
}

