function isChessProject(preview: StudioPreview) {
  const configFile = preview.files.find((file) => file.filePath === "studio-preview.json")?.content;
  try { if (JSON.parse(configFile ?? "{}").checkers?.gameType === "chess") return true; } catch { /* Usa a detecção textual abaixo. */ }
  return /\b(xadrez|chess)\b/i.test(`${preview.project.name} ${preview.files.map((file) => file.content.slice(0, 700)).join(" ")}`);
}

function isAgendaProject(preview: StudioPreview) {
  return preview.project.projectType === "application" && /\b(agenda|agendamento|calend[áa]rio|planejamento|hor[áa]rio)\b/i.test(`${preview.project.name} ${preview.files.map((file) => file.content.slice(0, 700)).join(" ")}`);
}

type AgendaTheme = { primary: string; primaryDark: string; accent: string; brandName?: string };

function detectAgendaTheme(preview: StudioPreview): AgendaTheme {
  const configFile = preview.files.find((file) => file.filePath === "studio-preview.json")?.content;
  let configured = "violet";
  let brandName = "";
  try { const config = JSON.parse(configFile ?? "{}") as { agenda?: { primary?: string; brandName?: string } }; configured = String(config.agenda?.primary ?? "violet").toLowerCase(); brandName = String(config.agenda?.brandName ?? "").slice(0, 60); } catch { /* Usa o tema padrão. */ }
  const palettes: Record<string, [string, string, string]> = { violet: ["#8b5cf6", "#4f46e5", "#22d3ee"], pink: ["#ec4899", "#be185d", "#fbbf24"], yellow: ["#eab308", "#a16207", "#fb7185"], red: ["#ef4444", "#b91c1c", "#f59e0b"], green: ["#22c55e", "#15803d", "#38bdf8"], blue: ["#3b82f6", "#1d4ed8", "#22d3ee"] };
  const [primary, primaryDark, accent] = palettes[configured] ?? palettes.violet;
  return { primary, primaryDark, accent, brandName: brandName || undefined };
}

