function isCalculatorProject(preview: StudioPreview) {
  return /\b(calculadora|calculator|c[aá]lculo)\b/i.test(`${preview.project.name} ${preview.files.map((file) => file.content.slice(0, 700)).join(" ")}`);
}

function previewSource(preview: StudioPreview) {
  return `${preview.project.name} ${preview.files.map((file) => `${file.filePath} ${file.content.slice(0, 900)}`).join(" ")}`;
}

function isStoreProject(preview: StudioPreview) {
  return /\b(loja|store|shop|e-?commerce|cat[aá]logo|vendas?|produto|carrinho de compras|checkout)\b/i.test(previewSource(preview));
}

function isDeliveryProject(preview: StudioPreview) {
  return /\b(delivery|entrega|restaurante|card[aá]pio|pedido de comida|lanchonete|pizzaria)\b/i.test(previewSource(preview));
}

function isFormProject(preview: StudioPreview) {
  return /\b(formul[aá]rio|cadastro|inscri[cç][aã]o|contato|lead|or[cç]amento|solicita[cç][aã]o)\b/i.test(previewSource(preview));
}

function isCarProject(preview: StudioPreview) {
  return /\b(carrinho|carro|autom[oó]vel|ve[ií]culo|corrida|racing)\b/i.test(previewSource(preview));
}

function isAirplaneProject(preview: StudioPreview) {
  return /\b(avi[aã]o|aeronave|aviao|decolagem|pista de pouso|voo|flight)\b/i.test(previewSource(preview));
}

type UniversalPreviewTheme = { primary?: string; style?: string; objects?: string[]; features?: string[]; brandName?: string };
type CalculatorPreviewTheme = { scientific: boolean; racing: boolean; universal?: UniversalPreviewTheme };

function readPreviewConfig(preview: StudioPreview): { universal?: UniversalPreviewTheme; calculator?: { scientific?: boolean; racing?: boolean } } {
  try { return JSON.parse(preview.files.find((file) => file.filePath === "studio-preview.json")?.content ?? "{}") as { universal?: UniversalPreviewTheme; calculator?: { scientific?: boolean; racing?: boolean } }; } catch { return {}; }
}

function detectCalculatorPreviewTheme(preview: StudioPreview): CalculatorPreviewTheme {
  const config = readPreviewConfig(preview);
  const source = previewSource(preview).toLowerCase();
  return { scientific: Boolean(config.calculator?.scientific) || /cient[ií]fic|trigonometr|raiz quadrada/.test(source), racing: Boolean(config.calculator?.racing) || config.universal?.style === "racing", universal: config.universal };
}

